// SSE frame reducer: versioned frames to typed UI state (plain JS)
function reduceFrame(state, frame) {
  switch (frame.type) {
    case "token": return { ...state, partial: state.partial + frame.text };
    case "citations": return { ...state, citations: frame.items };
    case "done": return { ...state, phase: "complete", entity: frame.entity };
    case "error": return { ...state, phase: "error", error: frame };
    default: return state; // unknown frames ignored (forward tolerance)
  }
}
// Unknown-frame tolerance keeps v1 clients alive on v2 servers (Ch.1 contracts).

